#include <cstdio>
#include <algorithm>

using namespace std;

const int N = 4e5 + 5;
const long long oo = 1e18;

int n, k;
int a[N];
int last[N], dd[N];
long long s, d, ans;

void solve() {
	scanf("%d%d", &n, &k);
	for (int i = 1; i <= n; i++)
		last[i] = dd[i] = 0;
	s = 0;
	for (int i = 1; i <= n; i++) {
		scanf("%d", &a[i]);
		if (!last[a[i]])
			s += i - 1;
		else {
			int pre = last[a[i]];
			int mid = (pre + i) / 2;
			if ((pre + i) & 1) {
				dd[mid]--;
				dd[mid + 1]--;
			} else
				dd[mid] -= 2;
		}
		dd[i] += 2;
		last[a[i]] = i;
	}
	ans = oo;
	d = -k;
	for (int i = 1; i <= n; i++) {
		ans = min(ans, s);
		d += dd[i];
		s += d;
	}
	for (int i = 1; i <= k; i++)
		ans -= abs(i - (k + 1) / 2);
	printf("%lld\n", ans);
}

int main() {
	int T;
	scanf("%d", &T);
	while (T--)
		solve();
	return 0;
}
